diff --git a/os/nftrace.c b/os/nftrace.c
new file mode 100644
index 0000000..8d99129
--- /dev/null
+++ b/os/nftrace.c
@@ -0,0 +1,39 @@
+#include "nftrace.h"
+
+__attribute__((noinline))
+void nftrace_commit_point(const struct nftrace_record *record)
+{
+	if (record != 0)
+		__asm__ volatile("" : : "r"(*(volatile const uint64 *)record) : "memory");
+}
+
+static inline void emit(uint64 type, uint64 a0, uint64 a1, uint64 a2, uint64 a3)
+{
+	const struct nftrace_record record = { type, { a0, a1, a2, a3 } };
+	nftrace_commit_point(&record);
+}
+
+void nftrace_page_alloc(uint64 pa, uint64 free_pages, uint64 used_pages)
+{
+	emit(1, pa, 1, free_pages, used_pages);
+}
+
+void nftrace_page_free(uint64 pa, uint64 free_pages, uint64 used_pages)
+{
+	emit(5, pa, 1, free_pages, used_pages);
+}
+
+void nftrace_allocator_state(uint64 free_pages, uint64 used_pages)
+{
+	emit(6, free_pages, used_pages, 0, 0);
+}
+
+void nftrace_proc_fork(uint64 parent, uint64 child)
+{
+	emit(2, parent, child, 0, 0);
+}
+
+void nftrace_sched_switch(uint64 from_task, uint64 to_task, uint64 from_pid, uint64 to_pid)
+{
+	emit(4, from_task, to_task, from_pid, to_pid);
+}
diff --git a/os/nftrace.h b/os/nftrace.h
new file mode 100644
index 0000000..e1428ae
--- /dev/null
+++ b/os/nftrace.h
@@ -0,0 +1,18 @@
+#ifndef NFTRACE_H
+#define NFTRACE_H
+
+#include "types.h"
+
+struct nftrace_record {
+	uint64 type;
+	uint64 a[4];
+};
+
+void nftrace_commit_point(const struct nftrace_record *record);
+void nftrace_page_alloc(uint64 pa, uint64 free_pages, uint64 used_pages);
+void nftrace_page_free(uint64 pa, uint64 free_pages, uint64 used_pages);
+void nftrace_allocator_state(uint64 free_pages, uint64 used_pages);
+void nftrace_proc_fork(uint64 parent, uint64 child);
+void nftrace_sched_switch(uint64 from_task, uint64 to_task, uint64 from_pid, uint64 to_pid);
+
+#endif
diff --git a/os/proc.c b/os/proc.c
index 9187793..95af12e 100644
--- a/os/proc.c
+++ b/os/proc.c
@@ -4,6 +4,7 @@
 #include "trap.h"
 #include "vm.h"
 #include "queue.h"
+#include "nftrace.h"

 struct proc pool[NPROC];
 __attribute__((aligned(16))) char kstack[NPROC][PAGE_SIZE];
@@ -127,6 +128,7 @@ void scheduler()
 		tracef("swtich to proc %d", p - pool);
 		p->state = RUNNING;
 		current_proc = p;
+		nftrace_sched_switch((uint64)&idle, (uint64)p, (uint64)-1, p->pid);
 		swtch(&idle.context, &p->context);
 	}
 }
@@ -143,6 +145,7 @@ void sched()
 	struct proc *p = curr_proc();
 	if (p->state == RUNNING)
 		panic("sched running");
+	nftrace_sched_switch((uint64)p, (uint64)&idle, p->pid, (uint64)-1);
 	swtch(&p->context, &idle.context);
 }

@@ -194,6 +197,7 @@ int fork()
 	np->parent = p;
 	np->state = RUNNABLE;
 	add_task(np);
+	nftrace_proc_fork(p->pid, np->pid);
 	return np->pid;
 }

